(421, 1, '2026-01-25 10:09:40', '2026-01-25 10:09:40', '/* 1. Ẩn tiêu đề Trang chủ và ngày tháng thừa */\n.page-template-default .post-meta, \n.page-template-default .entry-header,\n.page-template-default .c-blog__heading {\n    display: none !important;\n}\n\n/* 2. Đẩy nội dung lên sát menu (xóa khoảng trắng) */\n.page-template-default .c-page-content {\n    padding-top: 0 !important;\n}\n\n/* 3. Chỉnh cho Slider full chiều rộng (nếu cần) */\n.c-page-content .content-area {\n    padding-top: 20px; /* Tạo 1 chút khoảng hở nhẹ cho đẹp */\n}', 'madara-child', '', 'publish', 'closed', 'closed', '', 'madara-child', '', '', '2026-01-25 10:09:40', '2026-01-25 10:09:40', '', 0, 'http://madara.test/madara-child/', 0, 'custom_css', '', 0, NULL),
(422, 1, '2026-01-25 10:09:40', '2026-01-25 10:09:40', '/* 1. Ẩn tiêu đề Trang chủ và ngày tháng thừa */\n.page-template-default .post-meta, \n.page-template-default .entry-header,\n.page-template-default .c-blog__heading {\n    display: none !important;\n}\n\n/* 2. Đẩy nội dung lên sát menu (xóa khoảng trắng) */\n.page-template-default .c-page-content {\n    padding-top: 0 !important;\n}\n\n/* 3. Chỉnh cho Slider full chiều rộng (nếu cần) */\n.c-page-content .content-area {\n    padding-top: 20px; /* Tạo 1 chút khoảng hở nhẹ cho đẹp */\n}', 'madara-child', '', 'inherit', 'closed', 'closed', '', '421-revision-v1', '', '', '2026-01-25 10:09:40', '2026-01-25 10:09:40', '', 421, 'http://madara.test/?p=422', 0, 'revision', '', 0, NULL),
