INSERT INTO `wp_snippets` (`id`, `name`, `description`, `code`, `tags`, `scope`, `condition_id`, `priority`, `active`, `modified`, `revision`, `cloud_id`) VALUES
(1, 'Make upload filenames lowercase', 'Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'sanitize_file_name\', \'mb_strtolower\' );', 'sample, media', 'global', 0, 10, -1, '2026-01-18 20:34:36', 1, NULL),
(2, 'Disable admin bar', 'Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );', 'sample, admin-bar', 'front-end', 0, 10, -1, '2026-01-18 20:34:36', 1, NULL),
(3, 'Allow smilies', 'Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );', 'sample', 'global', 0, 10, -1, '2026-01-18 20:34:36', 1, NULL),
(4, 'Current year', 'Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', '<?php echo date( \'Y\' ); ?>', 'sample, dates', 'content', 0, 10, -1, '2026-01-18 20:34:36', 1, NULL),
(5, 'LG Home Shortcode', '', 'function lg_get_latest_chapters( $post_id, $limit = 2 ) {\n	$raw = array();\n\n	if ( function_exists( \'wp_manga_get_latest_chapters\' ) ) {\n		$raw = wp_manga_get_latest_chapters( $post_id, $limit );\n	} elseif ( function_exists( \'madara_get_latest_chapters\' ) ) {\n		$raw = madara_get_latest_chapters( $post_id, $limit );\n	}\n\n	if ( ! is_array( $raw ) ) {\n		return array();\n	}\n\n	$chapters = array();\n	foreach ( $raw as $chapter ) {\n		$name = \'\';\n		$url  = \'\';\n\n		if ( is_array( $chapter ) ) {\n			$name = $chapter[\'chapter_name\'] ?? $chapter[\'chapter_title\'] ?? $chapter[\'title\'] ?? \'\';\n			$url  = $chapter[\'chapter_link\'] ?? $chapter[\'chapter_url\'] ?? $chapter[\'permalink\'] ?? \'\';\n		} elseif ( is_object( $chapter ) ) {\n			$name = $chapter->chapter_name ?? $chapter->post_title ?? \'\';\n			$url  = $chapter->chapter_link ?? $chapter->chapter_url ?? \'\';\n\n			if ( ! $url && isset( $chapter->ID ) ) {\n				$url = get_permalink( $chapter->ID );\n			}\n		} elseif ( is_string( $chapter ) ) {\n			$name = $chapter;\n		}\n\n		if ( $name ) {\n			$chapters[] = array(\n				\'name\' => $name,\n				\'url\'  => $url,\n			);\n		}\n	}\n\n	return array_slice( $chapters, 0, $limit );\n}\n\nadd_shortcode(\n	\'lg_home\',\n	function () {\n		if ( is_admin() ) {\n			return \'\';\n		}\n\n		$manga_type = post_type_exists( \'wp-manga\' ) ? \'wp-manga\' : ( post_type_exists( \'manga\' ) ? \'manga\' : \'post\' );\n\n		$featured = new WP_Query(\n			array(\n				\'post_type\'      => $manga_type,\n				\'posts_per_page\' => 10,\n				\'meta_key\'       => \'_wp_manga_views\',\n				\'orderby\'        => array(\n					\'meta_value_num\' => \'DESC\',\n					\'date\'           => \'DESC\',\n				),\n			)\n		);\n\n		$latest = new WP_Query(\n			array(\n				\'post_type\'      => $manga_type,\n				\'posts_per_page\' => 8,\n				\'orderby\'        => array(\n					\'modified\' => \'DESC\',\n					\'date\'     => \'DESC\',\n				),\n			)\n		);\n\n		ob_start();\n		?>\n		<style>\n		@import url(\'https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;700&family=Nunito:wght@400;700&display=swap\');\n		.lg-home {\n			font-family: \"Nunito\", \"Trebuchet MS\", sans-serif;\n			color: #16334a;\n			background: linear-gradient(180deg, #bfe8ff 0%, #e8f7ff 55%, #f7fbff 100%);\n			position: relative;\n			padding-bottom: 60px;\n			min-height: 100vh;\n		}\n		.lg-home::before {\n			content: \"\";\n			position: absolute;\n			inset: 0;\n			background:\n				radial-gradient(circle at 15% 18%, rgba(255,255,255,0.8) 0 120px, rgba(255,255,255,0) 160px),\n				radial-gradient(circle at 75% 12%, rgba(255,255,255,0.7) 0 140px, rgba(255,255,255,0) 190px),\n				radial-gradient(circle at 35% 35%, rgba(255,255,255,0.6) 0 100px, rgba(255,255,255,0) 150px);\n			pointer-events: none;\n		}\n		.lg-hero {\n			background: linear-gradient(180deg, rgba(255,255,255,0.7), rgba(207,236,255,0.4));\n			padding: 24px 16px 12px;\n			border-bottom: 2px solid rgba(22, 51, 74, 0.1);\n			position: relative;\n			z-index: 1;\n		}\n		.lg-hero-inner {\n			max-width: 1100px;\n			margin: 0 auto;\n			display: flex;\n			flex-direction: column;\n			gap: 12px;\n			align-items: center;\n		}\n		.lg-logo {\n			font-family: \"Baloo 2\", \"Comic Sans MS\", cursive;\n			text-align: center;\n			color: #3a6aa0;\n		}\n		.lg-logo-link {\n			font-size: 32px;\n			font-weight: 700;\n			text-decoration: none;\n			color: inherit;\n			letter-spacing: 1px;\n			text-shadow: 0 2px 0 rgba(255,255,255,0.8);\n		}\n		.lg-logo-sub {\n			display: block;\n			font-size: 13px;\n			color: #7a98b5;\n			margin-top: 2px;\n		}\n		.lg-nav-list {\n			display: flex;\n			gap: 20px;\n			flex-wrap: wrap;\n			justify-content: center;\n			list-style: none;\n			padding: 0;\n			margin: 0;\n			font-weight: 700;\n			text-transform: uppercase;\n			font-size: 13px;\n			letter-spacing: 0.5px;\n		}\n		.lg-nav-list a {\n			color: #2f4f6c;\n			text-decoration: none;\n			padding: 4px 8px;\n			border-radius: 999px;\n			transition: background 0.2s ease;\n		}\n		.lg-nav-list a:hover { background: rgba(255,255,255,0.7); }\n		.lg-section {\n			max-width: 1100px;\n			margin: 28px auto 0;\n			padding: 0 16px;\n			position: relative;\n			z-index: 1;\n		}\n		.lg-section-title { margin-bottom: 12px; }\n		.lg-section-pill {\n			font-family: \"Baloo 2\", \"Comic Sans MS\", cursive;\n			font-size: 16px;\n			padding: 6px 16px;\n			border-radius: 999px;\n			background: #e0f0ff;\n			color: #2e5d8f;\n			border: 2px solid #c1dcf4;\n			box-shadow: 0 3px 0 #c1dcf4;\n			display: inline-block;\n		}\n		.lg-section-ribbon {\n			font-family: \"Baloo 2\", \"Comic Sans MS\", cursive;\n			font-size: 18px;\n			padding: 6px 18px;\n			border-radius: 10px;\n			background: #ffffff;\n			color: #2c5f8f;\n			box-shadow: 0 4px 0 rgba(44, 95, 143, 0.15);\n			border: 2px dashed #b6d4f1;\n			display: inline-block;\n		}\n		.lg-card-row {\n			display: grid;\n			grid-auto-flow: column;\n			grid-auto-columns: minmax(120px, 1fr);\n			gap: 14px;\n			overflow-x: auto;\n			padding-bottom: 10px;\n			scroll-snap-type: x mandatory;\n		}\n		.lg-card {\n			background: rgba(255,255,255,0.85);\n			border-radius: 18px;\n			padding: 12px 12px 14px;\n			box-shadow: 0 12px 24px rgba(23,55,88,0.12);\n			border: 2px solid rgba(255,255,255,0.6);\n		}\n		.lg-card-featured { min-width: 140px; scroll-snap-align: start; }\n		.lg-card-link { text-decoration: none; color: inherit; display: block; }\n		.lg-card-cover {\n			display: block;\n			width: 100%;\n			height: 170px;\n			border-radius: 14px;\n			background-size: cover;\n			background-position: center;\n			box-shadow: inset 0 0 0 1px rgba(255,255,255,0.6);\n		}\n		.lg-card-featured .lg-card-cover { height: 190px; }\n		.lg-card-title { margin-top: 8px; font-weight: 700; font-size: 14px; text-align: center; }\n		.lg-card-meta {\n			display: flex;\n			flex-direction: column;\n			gap: 6px;\n			margin-top: 10px;\n			font-size: 12px;\n			color: #3b5a74;\n		}\n		.lg-chapter {\n			padding: 4px 8px;\n			border-radius: 999px;\n			background: rgba(255,255,255,0.8);\n			border: 1px solid rgba(59,90,116,0.2);\n			text-decoration: none;\n			color: inherit;\n			display: inline-flex;\n			justify-content: center;\n		}\n		.lg-time { font-size: 11px; text-align: center; color: #7b97b1; }\n		.lg-grid {\n			display: grid;\n			grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\n			gap: 16px;\n		}\n		@media (min-width: 768px) {\n			.lg-hero-inner { flex-direction: row; justify-content: space-between; }\n			.lg-logo { text-align: left; }\n		}\n		</style>\n\n		<main class=\"lg-home\">\n			<header class=\"lg-hero\">\n				<div class=\"lg-hero-inner\">\n					<div class=\"lg-logo\">\n						<a class=\"lg-logo-link\" href=\"<?php echo esc_url( home_url( \'/\' ) ); ?>\">\n							<?php echo esc_html( get_bloginfo( \'name\' ) ); ?>\n						</a>\n						<span class=\"lg-logo-sub\">Team dich truyen</span>\n					</div>\n					<nav class=\"lg-nav\">\n						<ul class=\"lg-nav-list\">\n							<li><a href=\"<?php echo esc_url( home_url( \'/\' ) ); ?>\">Trang chu</a></li>\n							<li><a href=\"<?php echo esc_url( home_url( \'/manga/\' ) ); ?>\">Manga</a></li>\n							<li><a href=\"<?php echo esc_url( home_url( \'/truyen-ngan/\' ) ); ?>\">Truyen ngan</a></li>\n							<li><a href=\"<?php echo esc_url( home_url( \'/tin-tuc/\' ) ); ?>\">Tin tuc</a></li>\n						</ul>\n					</nav>\n				</div>\n			</header>\n\n			<section class=\"lg-section lg-featured\">\n				<div class=\"lg-section-title\"><span class=\"lg-section-pill\">Truyen hot</span></div>\n				<div class=\"lg-card-row\">\n					<?php if ( $featured->have_posts() ) : ?>\n						<?php while ( $featured->have_posts() ) : ?>\n							<?php $featured->the_post(); ?>\n							<?php $thumb = get_the_post_thumbnail_url( get_the_ID(), \'medium\' ); ?>\n							<article class=\"lg-card lg-card-featured\">\n								<a class=\"lg-card-link\" href=\"<?php the_permalink(); ?>\">\n									<span class=\"lg-card-cover\" style=\"background-image:url(\'<?php echo esc_url( $thumb ); ?>\');\"></span>\n									<span class=\"lg-card-title\"><?php the_title(); ?></span>\n								</a>\n							</article>\n						<?php endwhile; ?>\n						<?php wp_reset_postdata(); ?>\n					<?php endif; ?>\n				</div>\n			</section>\n\n			<section class=\"lg-section lg-latest\">\n				<div class=\"lg-section-title\"><span class=\"lg-section-ribbon\">Moi cap nhat</span></div>\n				<div class=\"lg-grid\">\n					<?php if ( $latest->have_posts() ) : ?>\n						<?php while ( $latest->have_posts() ) : ?>\n							<?php $latest->the_post(); ?>\n							<?php\n							$thumb    = get_the_post_thumbnail_url( get_the_ID(), \'medium\' );\n							$chapters = lg_get_latest_chapters( get_the_ID(), 2 );\n							$time     = human_time_diff( get_post_modified_time( \'U\', false, get_the_ID() ), current_time( \'timestamp\' ) );\n							?>\n							<article class=\"lg-card\">\n								<a class=\"lg-card-link\" href=\"<?php the_permalink(); ?>\">\n									<span class=\"lg-card-cover\" style=\"background-image:url(\'<?php echo esc_url( $thumb ); ?>\');\"></span>\n									<span class=\"lg-card-title\"><?php the_title(); ?></span>\n								</a>\n								<div class=\"lg-card-meta\">\n									<?php foreach ( $chapters as $chapter ) : ?>\n										<?php if ( $chapter[\'url\'] ) : ?>\n											<a class=\"lg-chapter\" href=\"<?php echo esc_url( $chapter[\'url\'] ); ?>\">\n												<?php echo esc_html( $chapter[\'name\'] ); ?>\n											</a>\n										<?php else : ?>\n											<span class=\"lg-chapter\"><?php echo esc_html( $chapter[\'name\'] ); ?></span>\n										<?php endif; ?>\n									<?php endforeach; ?>\n									<span class=\"lg-time\"><?php echo esc_html( $time ); ?> truoc</span>\n								</div>\n							</article>\n						<?php endwhile; ?>\n						<?php wp_reset_postdata(); ?>\n					<?php endif; ?>\n				</div>\n			</section>\n		</main>\n		<?php\n		return ob_get_clean();\n	}\n);\n', '', 'global', 0, 10, 1, '2026-01-18 20:50:05', 1, NULL);
